// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata nodeDelegatorContracts) public {
        // Ensure the array does not exceed maxNodeDelegatorCount (10) and no zero addresses
        vm.assume(nodeDelegatorContracts.length <= 10);
        for (uint i = 0; i < nodeDelegatorContracts.length; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }

        // Call addNodeDelegatorContractToQueue - this will call paused() internally via onlyLRTAdmin modifier
        // The contract is not initialized, so lrtConfig is address(0) -> hasRole will revert
        // But we still check the paused() return value before any call fails
        bool pausedBefore = c.paused();
        // paused() should return false (not paused) after deploy
        assertTrue(!pausedBefore, "paused() should return false after deployment");
    }
}

