// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address[] calldata addrs) public {
        // Filter out zero addresses to avoid revert due to UtilLib.checkNonZeroAddress
        uint256 validCount = 0;
        for (uint256 i = 0; i < addrs.length; i++) {
            if (addrs[i] != address(0)) {
                validCount++;
            }
        }
        // Bound to ensure addrs length plus existing queue length <= maxNodeDelegatorCount
        uint256 currentLengthBefore = c.nodeDelegatorQueue().length;
        vm.assume(currentLengthBefore + addrs.length <= 10);

        // Also assume at least one valid address to make the call meaningful
        vm.assume(validCount > 0);

        uint256 initialLength = c.nodeDelegatorQueue().length;
        c.addNodeDelegatorContractToQueue(addrs);
        uint256 finalLength = c.nodeDelegatorQueue().length;
        assertTrue(finalLength == initialLength + validCount);
    }
}

