pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata nodeDelegatorContracts) public {
        // Save the length before the call
        uint256 lengthBefore = c.nodeDelegatorQueue().length;

        // Attempt to call addNodeDelegatorContractToQueue
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.addNodeDelegatorContractToQueue.selector, nodeDelegatorContracts));

        // Assert that if the call in the reference would succeed (i.e., success is false here means mutation causes revert),
        // the length remains unchanged. In the reference, the call would succeed, increasing length.
        // But our rule: the length must change if the call succeeds, else remain same.
        // Simpler: For the mutant that always reverts, the length is unchanged.
        // For the reference, if input is valid, length increases.
        // So the general invariant: length change is consistent with success.
        uint256 lengthAfter = c.nodeDelegatorQueue().length;

        // The general rule: If the call succeeds, lengthAfter must be > lengthBefore (but we can't assume valid input).
        // Instead, we test that the mutant breaks: for any input, the length never changes.
        // But the reference may revert for invalid input (zero addresses?) — we avoid that by assuming non-zero.
        vm.assume(nodeDelegatorContracts.length <= 10); // maxNodeDelegatorCount is 10
        for (uint256 i = 0; i < nodeDelegatorContracts.length; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }

        // Now in the reference, the call always succeeds (since all addresses are non-zero and count <= max).
        // In the mutant, it always reverts.
        assertTrue(success == true || lengthAfter == lengthBefore);
    }
}

