pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata addrs) public {
        // Assume the caller is not an LRTAdmin (default role 0x00)
        // Since the contract uses onlyLRTAdmin on addNodeDelegatorContractToQueue,
        // a random address will revert before any state change.
        vm.assume(addrs.length > 0 && addrs[0] != address(0));
        address[] memory queueBefore = c.getNodeDelegatorQueue();
        uint256 lengthBefore = queueBefore.length;

        // Call as a non-admin (any address without admin role)
        vm.prank(address(0x1234));
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.addNodeDelegatorContractToQueue.selector, addrs));

        // Expected: call reverts because caller is not admin, so queue unchanged
        assertTrue(!success);
        address[] memory queueAfter = c.getNodeDelegatorQueue();
        assertTrue(queueAfter.length == lengthBefore);
    }
}

