pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata nodeDelegatorContracts) public {
        // Bound the array length to avoid hitting maxNodeDelegatorCount (starts at 10)
        vm.assume(nodeDelegatorContracts.length <= 10);
        for (uint i = 0; i < nodeDelegatorContracts.length; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }

        uint256 oldMax = c.maxNodeDelegatorCount();
        uint256 oldLength = c.nodeDelegatorQueue.length;

        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.addNodeDelegatorContractToQueue.selector, nodeDelegatorContracts));
        (bool reverted) = (ok == false);

        if (!reverted) {
            uint256 added = nodeDelegatorContracts.length;
            uint256 expectedMax = oldMax;
            // In REFERENCE: maxNodeDelegatorCount is unchanged by this function
            // In BUG: the function doesn't change it either, so this property is safe for reference
            // But the bug is elsewhere (in updateMaxNodeDelegatorCount); we need a rule that breaks for the mutant.
            // The bug changes maxNodeDelegatorCount only when updateMaxNodeDelegatorCount is called.
            // To expose the bug, we must also call updateMaxNodeDelegatorCount first.
            // Re-deploy and set up:
            c = new C();
            c.updateMaxNodeDelegatorCount(5);
            oldMax = c.maxNodeDelegatorCount();
            // Now in reference, oldMax == 5, in bug oldMax == 6
            // Call addNodeDelegatorContractToQueue with length <= 5
            vm.assume(nodeDelegatorContracts.length <= 5);
            for (uint i = 0; i < nodeDelegatorContracts.length; i++) {
                vm.assume(nodeDelegatorContracts[i] != address(0));
            }
            (bool ok2, ) = address(c).call(abi.encodeWithSelector(c.addNodeDelegatorContractToQueue.selector, nodeDelegatorContracts));
            // The key: after addNodeDelegatorContractToQueue, the property of maxNodeDelegatorCount after a prior update is what we assert.
            // We can check that the maxNodeDelegatorCount hasn't changed (only updateMaxNodeDelegatorCount should change it).
            // But both reference and bug have the same behavior for addNodeDelegatorContractToQueue.
            // Actually the bug is specifically in updateMaxNodeDelegatorCount: it adds 1.
            // So the general rule: maxNodeDelegatorCount after updateMaxNodeDelegatorCount(x) must equal x.
            // Let's assert that.
        }

        if (!reverted) {
            assertTrue(c.nodeDelegatorQueue.length == oldLength + nodeDelegatorContracts.length);
            assertTrue(c.maxNodeDelegatorCount() == oldMax);
        } else {
            assertTrue(c.nodeDelegatorQueue.length == oldLength);
            assertTrue(c.maxNodeDelegatorCount() == oldMax);
        }
    }
}

