// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 x, uint256 y, address[] memory nodeDelegators) public {
        // Bound x to a reasonable range for maxNodeDelegatorCount
        x = bound(x, 1, 100);
        // Update maxNodeDelegatorCount to x
        c.updateMaxNodeDelegatorCount(x);

        // Capture current queue length
        uint256 lenBefore = c.nodeDelegatorQueue().length;

        // Bound number of node delegators to add to not exceed the remaining capacity (x - lenBefore)
        uint256 remainingCapacity = x - lenBefore;
        if (remainingCapacity > 0) {
            uint256 addCount = bound(y, 1, remainingCapacity);
            // Prepare array of unique addresses (avoid zero address)
            address[] memory toAdd = new address[](addCount);
            for (uint256 i = 0; i < addCount; i++) {
                toAdd[i] = address(uint160(uint256(keccak256(abi.encodePacked(i, block.timestamp)))));
                vm.assume(toAdd[i] != address(0));
            }
            c.addNodeDelegatorContractToQueue(toAdd);
        } else {
            // When no capacity, any non-empty array will revert; skip or try/catch
            vm.assume(false);
        }

        // Property: after operation, maxNodeDelegatorCount >= nodeDelegatorQueue.length
        uint256 finalMax = c.maxNodeDelegatorCount();
        uint256 finalLen = c.nodeDelegatorQueue().length;
        assertTrue(finalMax >= finalLen, "maxNodeDelegatorCount should be at least queue length");
    }
}

